mapper.select:
SELECT template_id, template_name, eabus_no, updated_at
FROM public.tb_electronic_approval_line_template
WHERE tenant_id = #{tenantId}
  AND owner_user_id = #{ownerUserId}
  AND eabus_no = #{eabusNo}
ORDER BY template_name ASC, template_id ASC

SELECT template_id, template_name, eabus_no, updated_at
FROM public.tb_electronic_approval_line_template
WHERE tenant_id = #{tenantId}
  AND owner_user_id = #{ownerUserId}
  AND template_id = #{templateId}

SELECT line.stage_order, line.participant_order,
       line.participant_type, line.participant_user_id
FROM public.tb_electronic_approval_line_template_info line
JOIN public.tb_electronic_approval_line_template template
  ON template.tenant_id = line.tenant_id
 AND template.template_id = line.template_id
WHERE template.tenant_id = #{tenantId}
  AND template.owner_user_id = #{ownerUserId}
  AND template.template_id = #{templateId}
ORDER BY line.stage_order, line.participant_order

SELECT EXISTS (
    SELECT 1
    FROM public.tb_electronic_approval_line_template
    WHERE tenant_id = #{tenantId}
      AND owner_user_id = #{ownerUserId}
      AND eabus_no = #{eabusNo}
      AND template_name = #{name}

      AND template_id <> #{excludeTemplateId}

)

INSERT INTO public.tb_electronic_approval_line_template (
    tenant_id, owner_user_id, eabus_no, template_name, created_at, updated_at
) VALUES (
    #{tenantId}, #{ownerUserId}, #{eabusNo}, #{name}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
)
RETURNING template_id

mapper.insert:
INSERT INTO public.tb_electronic_approval_line_template_info (
    tenant_id, template_id, stage_order, participant_order,
    participant_type, participant_user_id
) VALUES

    (
        #{tenantId}, #{templateId}, #{line.stageOrder}, #{line.participantOrder},
        #{line.participantType}, #{line.participantUserId}
    )

mapper.update:
UPDATE public.tb_electronic_approval_line_template
SET template_name = #{name},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND owner_user_id = #{ownerUserId}
  AND template_id = #{templateId}

mapper.delete:
DELETE FROM public.tb_electronic_approval_line_template
WHERE tenant_id = #{tenantId}
  AND owner_user_id = #{ownerUserId}
  AND template_id = #{templateId}
